const media={banner:svgMedia(bannerSVG(),{name:'glimmerdeep-banner.svg',alt:'A night landscape of Glimmerdeep: floating islands, a glowing crystal spire, glowmoths and a small adventurer with a lantern on a cliff'}),worldmap:svgMedia(worldMapSVG(),{name:'world-map.svg',alt:'Map of the Hollowed Lands: icy Frostfen in the north, green Mossy Hollows in the west, the dark Glimmer Caverns in the centre, volcanic Ashen Spires in the east and the Sunshard Dunes in the south'}),hollows:svgMedia(hollowsSVG(),{name:'mossy-hollows.svg',alt:'Mossy Hollows at dusk: giant red mushrooms, a lit wooden workshop, hanging moss and glowing moths'}),caverns:svgMedia(cavernsSVG(),{name:'glimmer-caverns.svg',alt:'A dark cavern lit by clusters of teal crystals around an underground pool, with an explorer holding a lantern'}),mural:svgMedia(muralSVG(),{name:'lantern-mural.svg',alt:'A carved stone mural: a crowned figure holding a lantern, a radiant crystal sun in the centre and a coiled wyrm'}),shard:svgMedia(sprite(...SPRITES.shard),{name:'glimmer-shard.svg',alt:'Pixel sprite of three teal Glimmer Shard crystals on a rock'}),pickaxe:svgMedia(sprite(...SPRITES.pickaxe),{name:'glimmer-pickaxe.svg',alt:'Pixel sprite of a pickaxe with a teal crystal head and a wooden handle'}),lantern:svgMedia(sprite(...SPRITES.lantern),{name:'storm-lantern.svg',alt:'Pixel sprite of a brass Storm Lantern with a glowing flame'}),bench:svgMedia(sprite(...SPRITES.bench),{name:'tinkers-bench.svg',alt:'Pixel sprite of a wooden Tinker’s Bench with a vise and a crystal'}),glowmoth:svgMedia(sprite(...SPRITES.glowmoth),{name:'glowmoth.svg',alt:'Pixel sprite of a Glowmoth with glowing mint-green wings'}),puffcap:svgMedia(sprite(...SPRITES.puffcap),{name:'puffcap.svg',alt:'Pixel sprite of a Puffcap, a small creature with a red spotted mushroom cap'}),crab:svgMedia(sprite(...SPRITES.crab),{name:'shardback-crab.svg',alt:'Pixel sprite of a Shardback Crab with crystals growing on its orange shell'}),wisp:svgMedia(sprite(...SPRITES.wisp),{name:'frost-wisp.svg',alt:'Pixel sprite of a pale blue Frost Wisp'}),wyrm:svgMedia(sprite(...SPRITES.wyrm),{name:'ember-wyrm.svg',alt:'Pixel sprite of the Ember Wyrm, a coiled orange serpent with a yellow eye'}),wren:svgMedia(sprite(...SPRITES.wren),{name:'wren.svg',alt:'Pixel portrait of Wren the Tinkerer: auburn hair, teal goggles, a yellow scarf'}),king:svgMedia(sprite(...SPRITES.king),{name:'hollow-king.svg',alt:'Pixel portrait of the Hollow King: a golden crown over a dark hood with glowing eyes'}),};const NAVBOX={type:'navbox',title:'Glimmerdeep',color:'#2a9d8f',groups:[{label:'World',links:'[[world|Overview & map]]\n[[biomes/mossy-hollows|Mossy Hollows]]\n[[biomes/glimmer-caverns|Glimmer Caverns]]\n[[world#Frostfen|Frostfen]]\n[[world#Ashen Spires|Ashen Spires]]\n[[world#Sunshard Dunes|Sunshard Dunes]]'},{label:'Creatures',links:'[[creatures|All creatures]]\n[[creatures/glowmoth|Glowmoth]]\n[[creatures#Puffcap|Puffcap]]\n[[creatures#Shardback Crab|Shardback Crab]]\n[[creatures#Frost Wisp|Frost Wisp]]\n[[creatures/ember-wyrm|Ember Wyrm]]'},{label:'Items',links:'[[items|All items]]\n[[items/glimmer-shard|Glimmer Shard]]\n[[items/glimmer-pickaxe|Glimmer Pickaxe]]\n[[items/storm-lantern|Storm Lantern]]\n[[crafting|Crafting]]'},{label:'Characters',links:'[[characters|Characters & factions]]\n[[characters/wren|Wren the Tinkerer]]\n[[characters/hollow-king|The Hollow King]]'},{label:'Guides & lore',links:'[[guides/first-nights|Your first nights]]\n[[lore|Lore]]\n[[patch-history|Patch history]]\n[[help|Help]]'},],};const SPOILER_WARNING={type:'callout',kind:'warning',title:'Spoiler warning',text:'This article reveals late-game story details and the ending of Glimmerdeep. Spoilers are hidden until you click them.'};const worldDiagram={type:'diagram',media:'worldmap',labels:'always',align:'full',caption:'The Hollowed Lands as of version 1.3. Click a region or a marker; regions with their own article open it.',items:[...Object.entries(REGIONS).map(([id,g])=>({id,shape:'poly',pts:g.pts,label:g.label,link:g.link,color:'#e8d39a'})),{id:'grove',shape:'point',x:16,y:30,lx:8,ly:12,label:'Glowmoth Grove',link:'creatures/glowmoth',color:'#5fe0bf'},{id:'workshop',shape:'point',x:30,y:56,lx:8,ly:70,label:'Wren’s Workshop',link:'characters/wren',color:'#ffcf6b'},{id:'glade',shape:'point',x:38,y:50,lx:32,ly:76,label:'Starting Glade',link:'guides/first-nights',note:'Where every new game begins',color:'#ffcf6b'},{id:'guild',shape:'point',x:60,y:12,lx:66,ly:3,label:'Lantern Guild Hall',link:'characters#Lantern Guild',color:'#ffcf6b'},{id:'caldera',shape:'point',x:84,y:24,lx:88,ly:7,label:'Wyrm’s Caldera',link:'creatures/ember-wyrm',note:'Boss arena',color:'#ff7a3d'},{id:'throne',shape:'point',x:58,y:52,lx:84,ly:70,label:'Hollow Throne',link:'characters/hollow-king',note:'Spoilers!',color:'#9df7ff'},{id:'isles',shape:'point',x:91,y:82,lx:76,ly:95,label:'Shardback Isles',link:'creatures#Shardback Crab',color:'#5fe0bf'},],};const mainPage={slug:'main-page',title:'Glimmerdeep Wiki',toc:'off',layout:'wide',summary:'The fan-run encyclopedia of Glimmerdeep, the crafting-and-exploration game about relighting a world that lost its sun.',blocks:[{type:'banner',style:'overlay',media:'banner',link:'world',button:'Explore the world',title:'Welcome to the Glimmerdeep Wiki',text:'The fan-run encyclopedia of **Glimmerdeep**, the crafting-and-exploration game about relighting a world that lost its sun. **20 articles** about biomes, creatures, items, recipes and lore - and anyone can help. New here? Read the [[help|help page]].',},{type:'columns',ratio:'2:1',cols:[{blocks:[{type:'heading',text:'Featured article',level:'2'},{type:'media',media:'wyrm',link:'creatures/ember-wyrm',align:'left',width:160,layout:'split',caption:'The Ember Wyrm',text:'The **[[creatures/ember-wyrm|Ember Wyrm]]** is the boss of the [[world#Ashen Spires|Ashen Spires]], added in [[patch-history|version 1.2 “Embers”]]. Coiled in a volcanic caldera, it fights in three phases and punishes players who arrive without [[crafting|Frost Resin bombs]]. Defeating it drops the Ember Heart, one of the three keys to {{spoiler|the Hollow Throne}}.\n\n[[creatures/ember-wyrm|Read the full article →]]',},{type:'heading',text:'Explore the wiki',level:'2'},{type:'pagelist',source:'links',style:'cards',summary:false,links:['world','creatures','items','crafting','characters','guides/first-nights','lore','patch-history'].map((link)=>({link})),},]},{blocks:[{type:'callout',kind:'tip',title:'Did you know…',text:'- …that [[creatures/glowmoth|Glowmoths]] follow any light source, including the [[items/storm-lantern|Storm Lantern]] in your hand?\n- …that the [[items/glimmer-pickaxe|Glimmer Pickaxe]] was made slower in version 1.2 after speedrunners mined straight into the deepest cavern?\n- …that [[characters/wren|Wren]] repairs any tool for free if you bring her a [[items/glimmer-shard|Glimmer Shard]]?\n- …that the word “Glimmerdeep” is spoken only once in the whole game, by {{spoiler|the Hollow King, in his last line}}?',},{type:'timeline',title:'Latest updates',style:'compact',items:[{date:'30 June 2026',title:'1.3 “Tinker’s Toolbox”',text:'Wren’s questline and a crafting overhaul.',link:'patch-history'},{date:'8 August 2025',title:'1.2 “Embers”',text:'The Ashen Spires and the Ember Wyrm.',link:'creatures/ember-wyrm'},{date:'20 November 2024',title:'1.1 “Frostfen”',text:'A frozen biome in the north.',link:'world'},],},{type:'callout',kind:'info',title:'New to the game?',text:'Start with [[guides/first-nights|Surviving your first nights]] - in a *Beginner* or an *Advanced* version - then learn the [[crafting|crafting]] basics.'},]},],},NAVBOX,],};const world={slug:'world',title:'The Hollowed Lands',cats:['biomes'],image:'worldmap',layout:'wide',summary:'The world of Glimmerdeep: five biomes on one continent, from the frozen north to the crystal caverns at its heart. Interactive map.',blocks:[{type:'infobox',title:'Glimmerdeep',subtitle:'the game',image:'banner',caption:'Key art of Glimmerdeep.',color:'#2a9d8f',rows:[{label:'Developer',value:'Pebblefox Studio (fictional)'},{label:'Genre',value:'Crafting, exploration, survival'},{label:'Modes',value:'Single-player, co-op for up to 4'},{label:'Full release',value:'14 March 2024 (1.0)'},{label:'Current version',value:'[[patch-history|1.3 “Tinker’s Toolbox”]]'},{label:'Build ID',value:'`gd-1.3.2-r5521`',layer:'ids'},],},{type:'text',text:'The **Hollowed Lands** are the single continent on which Glimmerdeep is played. According to the [[lore|in-game myths]], the land was once lit by the First Lantern, a sun made of crystal; when it went dark, its light shattered into the [[items/glimmer-shard|Glimmer Shards]] that players mine today. The continent is split into five biomes around the [[biomes/glimmer-caverns|Glimmer Caverns]], an underground region that sinks towards the world’s centre.',},worldDiagram,{type:'table',caption:'Biomes at a glance',head:'row',sortable:true,striped:true,rows:[['Biome','Danger (1–5)','Key resources','Added in'],['[[biomes/mossy-hollows|Mossy Hollows]]','1','Moss fibre, Puffcap Spores, copper','0.1'],['[[biomes/glimmer-caverns|Glimmer Caverns]]','4','[[items/glimmer-shard|Glimmer Shards]], Glow Dust','0.5'],['[[#Frostfen|Frostfen]]','3','Frost Resin, pine wood','1.1'],['[[#Ashen Spires|Ashen Spires]]','5','Ember Oil, Wyrm Scale','1.2'],['[[#Sunshard Dunes|Sunshard Dunes]]','?','Sunglass (unreleased)','1.4 (beta)'],],},{type:'heading',text:'Mossy Hollows',level:'2'},{type:'hatnote',kind:'main',text:'[[biomes/mossy-hollows]]'},{type:'text',text:'The green, mushroom-filled starting biome in the west. Every new game begins in the Starting Glade here, a short walk from [[characters/wren|Wren’s Workshop]].'},{type:'heading',text:'Glimmer Caverns',level:'2'},{type:'hatnote',kind:'main',text:'[[biomes/glimmer-caverns]]'},{type:'text',text:'A vast underground biome below the centre of the map, lit only by crystals and whatever light you bring. Its deepest layer hides {{spoiler|the Hollow Throne}}.'},{type:'heading',text:'Frostfen',level:'2'},{type:'text',text:'A frozen marsh in the north, added in version 1.1. The cold drains your stamina unless you stay near a fire or a lit [[items/storm-lantern|Storm Lantern]]. [[creatures#Frost Wisp|Frost Wisps]] drift over the ice at night, and the [[characters#Lantern Guild|Lantern Guild]] keeps its hall on the frozen lake.'},{type:'heading',text:'Ashen Spires',level:'2'},{type:'text',text:'Volcanic towers in the east, added in version 1.2 “Embers”. Lava rivers, the hostile [[characters#Ashborn|Ashborn]] and, in a caldera at the top, the [[creatures/ember-wyrm|Ember Wyrm]]. Bring fire resistance and plenty of [[crafting|Frost Resin bombs]].'},{type:'heading',text:'Sunshard Dunes',level:'2'},{type:'text',text:'A desert in the south that appears on the map but cannot yet be entered. Pebblefox Studio has announced it for version 1.4; a public beta started in September 2026.'},{type:'callout',kind:'note',title:'Datamined (unconfirmed)',layer:'datamined',text:'Files in the 1.4 beta mention a creature called the *Glass Strider* and an item called *Sunglass*. Treat these names as unconfirmed until release.'},NAVBOX,],};const mossyHollows={slug:'biomes/mossy-hollows',parent:'world',title:'Mossy Hollows',cats:['biomes'],image:'hollows',summary:'The starting biome of Glimmerdeep: giant mushrooms, gentle creatures and Wren’s Workshop.',blocks:[{type:'infobox',title:'Mossy Hollows',image:'hollows',caption:'Dusk in the Hollows, with Wren’s Workshop lit up.',color:'#4f8f4a',rows:[{label:'Type',value:'Surface biome'},{label:'Danger',value:'★☆☆☆☆'},{label:'Light',value:'Dim by day, dark at night'},{label:'Creatures',value:'[[creatures/glowmoth|Glowmoth]], [[creatures#Puffcap|Puffcap]]'},{label:'Resources',value:'Moss fibre, Puffcap Spores, copper ore, wood'},{label:'Faction',value:'[[characters#Rootkin|Rootkin]]'},{label:'Added in',value:'0.1'},{label:'Biome ID',value:'`biome:mossy_hollows`',layer:'ids'},],},{type:'text',text:'The **Mossy Hollows** are the biome where every game of Glimmerdeep begins: a valley of moss, giant mushrooms and slow streams on the western side of [[world|the Hollowed Lands]]. Very little here wants to hurt you, which makes it the best place to learn [[crafting|crafting]] and build a first base.\n\n'+'## Features\n- **The Starting Glade**, where new games spawn - see [[guides/first-nights|Surviving your first nights]].\n- **[[characters/wren|Wren’s Workshop]]**, a cottage with a smoking chimney and the only [[crafting#Tinker’s Bench|Tinker’s Bench]] you can use before finding your own.\n- **Rootkin villages**, where the moss-folk trade seeds and rope for copper.\n- **Glowmoth Grove**, a clearing where hundreds of [[creatures/glowmoth|Glowmoths]] gather on summer nights.\n\n'+'## Creatures\nThe Hollows are home to the harmless [[creatures/glowmoth|Glowmoth]] and the grumpy [[creatures#Puffcap|Puffcap]], which only fights back when kicked. At night a few [[creatures#Frost Wisp|Frost Wisps]] stray south from Frostfen.\n\n'+'## Resources',},{type:'table',head:'row',striped:true,sortable:true,rows:[['Resource','Where','Tool','Used for'],['Moss fibre','Any mossy rock','Hands','Moss Rope, bandages'],['Puffcap Spores','Puffcaps (drop)','-','Sleep potions, farming'],['Copper ore','Riverbanks','Wooden Pickaxe','Copper Ingot'],['Wood','Trees','Axe','Workbench, handles']],},{type:'text',text:'## Trivia\n- The Hollows’ music track is called “Under the Canopy”.\n- The biome was the only one in the 0.1 pre-alpha, when it was still called “The Green”.\n- If you sleep in Wren’s spare bed, {{spoiler|she leaves a letter on the table addressed to someone called “Grandfather”}}.',},NAVBOX,],};const glimmerCaverns={slug:'biomes/glimmer-caverns',parent:'world',title:'Glimmer Caverns',cats:['biomes'],image:'caverns',summary:'A vast underground biome lit by crystals, the only reliable source of Glimmer Shards - and much more dangerous the deeper you go.',blocks:[{type:'infobox',title:'Glimmer Caverns',image:'caverns',caption:'A crystal cluster in the Shardfields.',color:'#3d335e',rows:[{label:'Type',value:'Underground biome'},{label:'Danger',value:'★★★★☆'},{label:'Light',value:'Darkness - bring a [[items/storm-lantern|lantern]]'},{label:'Creatures',value:'[[creatures/glowmoth|Glowmoth]] (upper layers), Cave Lurkers'},{label:'Resources',value:'[[items/glimmer-shard|Glimmer Shards]], Glow Dust, stone'},{label:'Added in',value:'0.5 (Early Access)'},{label:'Biome ID',value:'`biome:glimmer_caverns`',layer:'ids'},],},{type:'text',text:'The **Glimmer Caverns** are the underground heart of Glimmerdeep, reached through sinkholes in the [[biomes/mossy-hollows|Mossy Hollows]] and the plains around them. They are the only place where [[items/glimmer-shard|Glimmer Shards]] grow in large clusters, so every player comes here sooner or later - usually with a [[items/glimmer-pickaxe|better pickaxe]] in mind.',},{type:'callout',kind:'warning',title:'The darkness meter',text:'Away from light, your darkness meter fills. When it is full you start losing health. A lit [[items/storm-lantern|Storm Lantern]] or a cluster of shards keeps it empty.'},{type:'text',text:'## Layers\nThe caverns are split into four layers, each darker and more dangerous than the one above.',},{type:'table',head:'row',striped:true,rows:[['Layer','Depth','Light','Notable'],['Upper Galleries','0–40','Shard light','Glowmoths, easy shards'],['Shardfields','40–90','Patchy','Large shard clusters'],['The Drowned Halls','90–140','None','Flooded tunnels, Cave Lurkers'],['{{spoiler|The Hollow Throne}}','{{spoiler|140+}}','{{spoiler|None}}','{{spoiler|Final boss arena}}'],],},{type:'callout',kind:'spoiler',title:'What lies at the bottom (spoilers)',text:'The lowest layer opens only after you collect three keys: the Ember Heart from the [[creatures/ember-wyrm|Ember Wyrm]], the Frost Crown from the Lantern Guild’s questline and Wren’s Toolbox. Beyond the gate waits [[characters/hollow-king|the Hollow King]].',},{type:'seealso',items:[{link:'items/glimmer-shard',label:'Glimmer Shard'},{link:'guides/first-nights',label:'Surviving your first nights',note:'includes a first trip underground'},{link:'lore',label:'Lore of the First Lantern'}]},NAVBOX,],};const creatures={slug:'creatures',title:'Creatures',cats:['creatures'],image:'glowmoth',summary:'Every creature of Glimmerdeep, with a sortable table comparing health, damage, speed and drops.',blocks:[{type:'text',text:'Creatures in Glimmerdeep are **passive** (never attack), **neutral** (fight back when hit) or **hostile**. Bosses have their own articles. Click a column heading in the table to sort it.'},{type:'gallery',title:'Bestiary',style:'grid',size:'s',items:[{media:'glowmoth',caption:'Glowmoth',link:'creatures/glowmoth'},{media:'puffcap',caption:'Puffcap',link:'creatures#Puffcap'},{media:'crab',caption:'Shardback Crab',link:'creatures#Shardback Crab'},{media:'wisp',caption:'Frost Wisp',link:'creatures#Frost Wisp'},{media:'wyrm',caption:'Ember Wyrm',link:'creatures/ember-wyrm'},{media:'king',caption:'The Hollow King',link:'characters/hollow-king'},],},{type:'table',caption:'Creature stats (version 1.3, normal difficulty)',head:'row',sortable:true,striped:true,rows:[['Creature','Biome','Health','Damage','Speed','Drops','Behaviour'],['[[creatures/glowmoth|Glowmoth]]','Mossy Hollows, Caverns','6','0','1.4','Glow Dust','Passive'],['[[#Puffcap|Puffcap]]','Mossy Hollows','14','3','0.8','Puffcap Spores','Neutral'],['[[#Shardback Crab|Shardback Crab]]','Shardback Isles','30','6','0.6','Glimmer Shard, Crab Shell','Neutral'],['[[#Frost Wisp|Frost Wisp]]','Frostfen','18','5','1.6','Frost Resin','Hostile at night'],['Ashborn Zealot','Ashen Spires','40','9','1.0','Ember Cloth','Hostile'],['[[creatures/ember-wyrm|Ember Wyrm]]','Ashen Spires','1200','25','1.2','Wyrm Scale, Ember Heart','Boss'],['[[characters/hollow-king|The Hollow King]]','{{spoiler|Glimmer Caverns}}','2000','30','1.0','-','Final boss'],],},{type:'heading',text:'Puffcap',level:'2'},{type:'media',media:'puffcap',align:'right',width:140,caption:'A Puffcap'},{type:'text',text:'A small walking mushroom of the [[biomes/mossy-hollows|Mossy Hollows]]. Puffcaps ignore players until hit, then release a cloud of sleepy spores. Their spores are the main ingredient of sleep potions.{{layer|ids| ID: `creature:puffcap`}}'},{type:'heading',text:'Shardback Crab',level:'2'},{type:'media',media:'crab',align:'right',width:140,caption:'A Shardback Crab'},{type:'text',text:'A crab that grows [[items/glimmer-shard|Glimmer Shards]] on its shell, found only on the Shardback Isles off the south-east coast. Killing one drops 1–3 shards - the only way to get shards without going underground.{{layer|ids| ID: `creature:shardback_crab`}}'},{type:'heading',text:'Frost Wisp',level:'2'},{type:'media',media:'wisp',align:'right',width:140,caption:'A Frost Wisp'},{type:'text',text:'A drifting spirit of [[world#Frostfen|Frostfen]], hostile at night. Its touch slows you down; it avoids lit [[items/storm-lantern|Storm Lanterns]]. Frost Resin from wisps makes the bombs that work so well against the [[creatures/ember-wyrm|Ember Wyrm]].{{layer|ids| ID: `creature:frost_wisp`}}'},NAVBOX,],};const glowmoth={slug:'creatures/glowmoth',parent:'creatures',title:'Glowmoth',cats:['creatures'],image:'glowmoth',summary:'A gentle, glowing moth of the Mossy Hollows that follows light sources and drops Glow Dust, the fuel of the Storm Lantern.',blocks:[{type:'infobox',title:'Glowmoth',image:'glowmoth',caption:'Glowmoth sprite',color:'#3fbf9f',rows:[{label:'Type',value:'Passive creature'},{label:'Biomes',value:'[[biomes/mossy-hollows|Mossy Hollows]], [[biomes/glimmer-caverns|Glimmer Caverns]] (upper layers)'},{label:'Health',value:'6'},{label:'Drops',value:'Glow Dust ×1–2'},{label:'Attracted by',value:'Light sources'},{label:'Tameable',value:'Yes (with Glow Dust)'},{label:'Added in',value:'0.5'},{label:'Creature ID',value:'`creature:glowmoth`',layer:'ids'},],},{type:'text',text:'The **Glowmoth** is a small passive creature with softly glowing wings. It is one of the first creatures new players meet in the [[biomes/mossy-hollows|Mossy Hollows]], and one of the most useful: its Glow Dust is the standard fuel of the [[items/storm-lantern|Storm Lantern]].\n\n'+'## Behaviour\nGlowmoths wander in small swarms and drift towards any light: torches, campfires, shard clusters and lanterns in a player’s hand. They never attack. When hit they scatter and drop Glow Dust; killing one is not necessary, and many players consider it bad manners.\n\n'+'## Taming\n1. Hold a lit [[items/storm-lantern|Storm Lantern]] and wait for a swarm to gather.\n2. Offer Glow Dust to one moth (use it while looking at the moth).\n3. A tamed Glowmoth follows you and lights a small radius around you, slowing your darkness meter in the [[biomes/glimmer-caverns|Glimmer Caverns]].\n\n'+'## Trivia\n- Glowmoths were added in 0.5 together with the Caverns, as a way to make the dark less punishing.\n- In co-op, a tamed Glowmoth follows whoever tamed it, even into another player’s base.',},{type:'callout',kind:'tip',title:'Tip',text:'A tamed Glowmoth counts as a light source for the [[guides/first-nights|darkness meter]], so it frees a hand for your [[items/glimmer-pickaxe|pickaxe]].'},{type:'callout',kind:'note',title:'Datamined (unconfirmed)',layer:'datamined',text:'The 1.4 beta files contain an unused “glowmoth_queen” model.'},NAVBOX,],};const emberWyrm={slug:'creatures/ember-wyrm',parent:'creatures',title:'Ember Wyrm',cats:['creatures','bosses'],image:'wyrm',summary:'The fire-breathing boss of the Ashen Spires, fought in three phases in a volcanic caldera. Drops the Ember Heart.',blocks:[{type:'hatnote',kind:'about',text:'“Wyrm” redirects here. For the wyrms of the creation myth, see [[lore]].'},{type:'infobox',title:'Ember Wyrm',image:'wyrm',caption:'Ember Wyrm sprite',color:'#e2572b',rows:[{label:'Type',value:'Boss'},{label:'Location',value:'Wyrm’s Caldera, [[world#Ashen Spires|Ashen Spires]]'},{label:'Health',value:'1,200 (+600 per extra co-op player)'},{label:'Damage',value:'25–40 (fire)'},{label:'Weakness',value:'Frost Resin bombs'},{label:'Drops',value:'Wyrm Scale ×3–5, Ember Heart'},{label:'Added in',value:'[[patch-history|1.2 “Embers”]]'},{label:'Creature ID',value:'`boss:ember_wyrm`',layer:'ids'},],},{type:'text',text:'The **Ember Wyrm** is the boss of the [[world#Ashen Spires|Ashen Spires]] and one of three guardians whose keys open the deepest layer of the [[biomes/glimmer-caverns|Glimmer Caverns]]. It sleeps coiled in a caldera at the top of the tallest spire and wakes when a player steps onto the ash field around it.{{ref|name=embers|{{cite|author=Pebblefox Studio|title=Glimmerdeep 1.2 “Embers” patch notes|work=Pebblefox developer log|year=2025}}}}\n\n'+'## Preparation\n- [ ] Fire resistance potion (Puffcap Spores + Frost Resin)\n- [ ] At least 6 Frost Resin bombs - see [[crafting]]\n- [ ] A [[items/glimmer-pickaxe|Glimmer Pickaxe]] or better, to dig cover in phase 2\n- [ ] Food for 10 minutes\n\n'+'## Phases',},{type:'table',head:'row',striped:true,rows:[['Phase','Health','Main attacks','What to do'],['1. Coiled','100–60%','Tail sweep, ember spit','Stay at medium range; bomb the head when it rears.'],['2. Molten','60–25%','Lava rain, ash cloud','Dig into the caldera wall for cover; bomb between waves.'],['3. Unbound','25–0%','Charge, fire breath','Circle left; it cannot turn fast while charging.'],],},{type:'callout',kind:'spoiler',title:'After the fight (spoilers)',text:'When the Wyrm falls it does not die: it curls around the Ember Heart and turns to stone. The Heart is one of the three keys to [[characters/hollow-king|the Hollow King]]’s throne. Readers of the [[lore|lore]] have long argued about what the Wyrm was guarding.',},{type:'timeline',title:'Changes by version',style:'compact',items:[{date:'1.2',title:'Added',text:'With the Ashen Spires.'},{date:'1.2.1',title:'Health reduced',text:'1,500 → 1,200 for solo players.{{ref|{{cite|author=Pebblefox Studio|title=Hotfix 1.2.1|work=Pebblefox developer log|year=2025}}}}'},{date:'1.3',title:'Co-op scaling',text:'+600 health per extra player, instead of doubling.'},],},{type:'seealso',items:[{link:'guides/first-nights',label:'Surviving your first nights',note:'the Advanced version has damage numbers and bomb timing'},{link:'lore',label:'Lore'}]},{type:'references'},NAVBOX,],};const items={slug:'items',title:'Items',cats:['items'],image:'shard',summary:'Tools, resources and light sources of Glimmerdeep, with stack sizes and where to find them.',blocks:[{type:'text',text:'Items are anything you can carry in your inventory. They fall into three groups: **resources** (mined, gathered or dropped), **tools** (used to mine, fight or build) and **light sources**, which matter more in Glimmerdeep than in most games because of the darkness meter. Most items are made at a [[crafting|crafting station]].'},{type:'gallery',style:'grid',size:'s',items:[{media:'shard',caption:'Glimmer Shard',link:'items/glimmer-shard'},{media:'pickaxe',caption:'Glimmer Pickaxe',link:'items/glimmer-pickaxe'},{media:'lantern',caption:'Storm Lantern',link:'items/storm-lantern'},{media:'bench',caption:'Tinker’s Bench',link:'crafting#Tinker’s Bench'},],},{type:'table',caption:'Notable items',head:'row',sortable:true,striped:true,rows:[['Item','Type','Stack','Source'],['[[items/glimmer-shard|Glimmer Shard]]','Resource','64','Caverns, Shardback Crabs'],['Copper Ingot','Resource','64','Forge (copper ore)'],['Glow Dust','Resource','99','[[creatures/glowmoth|Glowmoths]]'],['Frost Resin','Resource','32','[[creatures#Frost Wisp|Frost Wisps]]'],['Wyrm Scale','Resource','16','[[creatures/ember-wyrm|Ember Wyrm]]'],['[[items/glimmer-pickaxe|Glimmer Pickaxe]]','Tool','1','Tinker’s Bench'],['[[items/storm-lantern|Storm Lantern]]','Light source','1','Workbench'],],},NAVBOX,],};const glimmerShard={slug:'items/glimmer-shard',parent:'items',title:'Glimmer Shard',cats:['items','resources'],image:'shard',summary:'The glowing teal crystal at the heart of Glimmerdeep’s crafting: needed for tier-3 tools, lanterns and almost every late-game recipe.',blocks:[{type:'infobox',title:'Glimmer Shard',image:'shard',caption:'Inventory icon',color:'#1f9aa3',rows:[{label:'Type',value:'Resource'},{label:'Rarity',value:'Uncommon'},{label:'Stack size',value:'64'},{label:'Found in',value:'[[biomes/glimmer-caverns|Glimmer Caverns]]; [[creatures#Shardback Crab|Shardback Crabs]]'},{label:'Tool needed',value:'Copper Pickaxe or better'},{label:'Light level',value:'4 (when placed)'},{label:'Added in',value:'0.1'},{label:'Item ID',value:'`item:glimmer_shard`',layer:'ids'},],},{type:'text',text:'A **Glimmer Shard** is a piece of glowing teal crystal - in the game’s story, a fragment of the light of the First Lantern (see [[lore]]). Shards are the signature resource of Glimmerdeep: you need them for tier-3 tools such as the [[items/glimmer-pickaxe|Glimmer Pickaxe]], for the [[crafting#Tinker’s Bench|Tinker’s Bench]] and for most late-game [[crafting|recipes]]. Placed on the ground, a shard gives off a little light.\n\n'+'## Obtaining\n- **Mining:** shard clusters grow on cavern walls, most densely in the Shardfields layer of the [[biomes/glimmer-caverns|Glimmer Caverns]]. A Copper Pickaxe gets 1 shard per cluster block; a Glimmer Pickaxe gets 2.\n- **Shardback Crabs:** each [[creatures#Shardback Crab|crab]] drops 1–3 shards.\n- **Trading:** [[characters/wren|Wren]] buys and sells shards from version 1.3.\n\n'+'## Used in',},{type:'table',head:'row',sortable:true,striped:true,rows:[['Recipe','Station','Shards'],['[[items/glimmer-pickaxe|Glimmer Pickaxe]]','Tinker’s Bench','3'],['[[crafting#Tinker’s Bench|Tinker’s Bench]]','Workbench','2'],['Shard Lamp','Workbench','1'],['Frost Resin bomb','Tinker’s Bench','1'],['Wyrmscale Pickaxe','Forge','4'],],},{type:'text',text:'## Lore\nIn-game books say the shards are “the First Lantern’s light, broken and buried”. {{spoiler|The hidden ending reveals where the rest of that light went.}}'},NAVBOX,],};const glimmerPickaxe={slug:'items/glimmer-pickaxe',parent:'items',title:'Glimmer Pickaxe',cats:['items','tools'],image:'pickaxe',summary:'The tier-3 pickaxe, crafted from Glimmer Shards and copper at a Tinker’s Bench. Mines twice as many shards per cluster.',blocks:[{type:'infobox',title:'Glimmer Pickaxe',image:'pickaxe',caption:'Inventory icon',color:'#1f9aa3',rows:[{label:'Type',value:'Tool'},{label:'Tier',value:'3 of 4'},{label:'Mining speed',value:'2.2×'},{label:'Durability',value:'900'},{label:'Crafted at',value:'[[crafting#Tinker’s Bench|Tinker’s Bench]]'},{label:'Added in',value:'0.5; changed in 1.2 and 1.3'},{label:'Item ID',value:'`tool:glimmer_pickaxe`',layer:'ids'},],},{type:'text',text:'The **Glimmer Pickaxe** is the third of the four pickaxe tiers and the one most players use for the longest. Its crystal head mines twice as many [[items/glimmer-shard|Glimmer Shards]] from each cluster, and it is the first pickaxe that can break the stone of the Drowned Halls in the [[biomes/glimmer-caverns|Glimmer Caverns]].\n\n'+'## Crafting\nThe recipe is **shaped**: the ingredients must sit in this pattern on the grid of a [[crafting#Tinker’s Bench|Tinker’s Bench]].',},{type:'table',caption:'Crafting grid',head:'none',compact:true,rows:[['[[items/glimmer-shard|Glimmer Shard]]','[[items/glimmer-shard|Glimmer Shard]]','[[items/glimmer-shard|Glimmer Shard]]'],['','Copper Rod',''],['','Copper Rod',''],],},{type:'table',caption:'Ingredients',head:'row',compact:true,rows:[['Ingredient','Amount','Where to get it'],['[[items/glimmer-shard|Glimmer Shard]]','3','Caverns, crabs'],['Copper Rod','2','Workbench: 1 Copper Ingot → 2 rods']],},{type:'text',text:'## Compared with other pickaxes',},{type:'table',head:'row',sortable:true,striped:true,rows:[['Pickaxe','Tier','Speed','Durability','Shards per cluster'],['Wooden Pickaxe','1','1.0','60','0'],['Copper Pickaxe','2','1.5','250','1'],['Glimmer Pickaxe','3','2.2','900','2'],['Wyrmscale Pickaxe','4','3.0','1600','2']],},{type:'timeline',title:'History',style:'compact',items:[{date:'0.5',title:'Added',text:'Mining speed 2.6×, durability 700.'},{date:'1.2',title:'Speed reduced',text:'2.6× → 2.2×, after speedrunners used it to dig straight to the deepest layer.{{ref|name=embers|{{cite|author=Pebblefox Studio|title=Glimmerdeep 1.2 “Embers” patch notes|work=Pebblefox developer log|year=2025}}}}'},{date:'1.3',title:'Durability raised',text:'700 → 900.'},],},{type:'callout',kind:'note',title:'Datamined (unconfirmed)',layer:'datamined',text:'The 1.4 beta adds an unused “socket” property to all tier-3 tools, possibly for upgrades.'},{type:'references'},NAVBOX,],};const stormLantern={slug:'items/storm-lantern',parent:'items',title:'Storm Lantern',cats:['items','tools'],image:'lantern',summary:'A portable brass lantern fuelled by Glow Dust - the most important item for surviving the dark.',blocks:[{type:'hatnote',kind:'about',text:'This article is about the item. For other uses, see [[lantern]].'},{type:'infobox',title:'Storm Lantern',image:'lantern',caption:'Inventory icon',color:'#c9933a',rows:[{label:'Type',value:'Light source'},{label:'Light radius',value:'9 blocks'},{label:'Fuel',value:'Glow Dust (1 per 4 min), Ember Oil (1 per 10 min)'},{label:'Crafted at',value:'[[crafting|Workbench]]'},{label:'Added in',value:'0.5'},{label:'Item ID',value:'`light:storm_lantern`',layer:'ids'},],},{type:'text',text:'The **Storm Lantern** is a portable light that keeps the darkness meter empty within nine blocks of the player. It is the first thing most guides tell you to make before going underground, and it attracts friendly [[creatures/glowmoth|Glowmoths]] while keeping hostile [[creatures#Frost Wisp|Frost Wisps]] away.\n\n'+'## Crafting\nShaped recipe, made at a Workbench:',},{type:'table',caption:'Crafting grid',head:'none',compact:true,rows:[['','Copper Ingot',''],['Glass Pane','Glow Dust','Glass Pane'],['','Copper Ingot','']],},{type:'table',caption:'Fuel',head:'row',sortable:true,compact:true,rows:[['Fuel','Burn time (min)','Source'],['Glow Dust','4','[[creatures/glowmoth|Glowmoths]]'],['Ember Oil','10','Ashen Spires'],['Shard Wick','25','Tinker’s Bench (1.3)']],},{type:'text',text:'## Tips\n- Hang the lantern on a wall (place it) to light a room; it does not burn fuel while placed next to a [[items/glimmer-shard|shard]].\n- In co-op, one lantern per two players is usually enough.\n- See [[guides/first-nights|Surviving your first nights]] for when to make your first one.',},NAVBOX,],};const crafting={slug:'crafting',title:'Crafting',cats:['guides'],image:'bench',summary:'How crafting works in Glimmerdeep: stations, shaped and shapeless recipes, and a table of the most useful recipes.',blocks:[{type:'media',media:'bench',align:'right',width:200,caption:'A Tinker’s Bench',},{type:'text',text:'Almost everything in Glimmerdeep is **crafted** from resources at a crafting station. Each station has a 3×3 grid; put ingredients on it and the result appears beside the grid.\n\n'+'## Crafting stations\n### Workbench\nMade from 10 wood. Handles basic tools, the [[items/storm-lantern|Storm Lantern]] and building parts.\n\n'+'### Tinker’s Bench\nUnlocked by [[characters/wren|Wren]]’s first quest. Needed for tier-3 tools such as the [[items/glimmer-pickaxe|Glimmer Pickaxe]] and for bombs. Recipe: a Workbench, 4 Copper Ingots and 2 [[items/glimmer-shard|Glimmer Shards]].\n\n'+'### Forge\nMade from 20 stone and 2 Copper Ingots. Smelts ore into ingots and makes tier-4 gear from [[creatures/ember-wyrm|Wyrm Scales]].\n\n'+'## Shaped and shapeless recipes\nIn a **shaped** recipe the pattern matters - a pickaxe has its head on top and its handle below. In a **shapeless** recipe only the ingredients matter. Recipe pages on this wiki show shaped recipes as a 3×3 grid.',},{type:'table',caption:'Useful recipes',head:'row',sortable:true,striped:true,rows:[['Output','Ingredients','Station','Shaped?'],['Workbench','Wood ×10','Hands','No'],['Copper Rod ×2','Copper Ingot ×1','Workbench','No'],['[[items/storm-lantern|Storm Lantern]]','Copper Ingot ×2, Glass Pane ×2, Glow Dust ×1','Workbench','Yes'],['Tinker’s Bench','Workbench, Copper Ingot ×4, Glimmer Shard ×2','Workbench','No'],['[[items/glimmer-pickaxe|Glimmer Pickaxe]]','Glimmer Shard ×3, Copper Rod ×2','Tinker’s Bench','Yes'],['Frost Resin bomb ×3','Frost Resin ×2, Glimmer Shard ×1','Tinker’s Bench','No'],['Wyrmscale Pickaxe','Wyrm Scale ×3, Glimmer Shard ×4, Copper Rod ×2','Forge','Yes'],],},{type:'glossary',title:'Crafting terms',layout:'cards',items:[{term:'Station',meaning:'A placed block with a crafting grid: Workbench, Tinker’s Bench or Forge.'},{term:'Shaped recipe',meaning:'A recipe whose ingredients must form a pattern on the grid.'},{term:'Shapeless recipe',meaning:'A recipe where only the ingredients count, not their places.'},{term:'Blueprint',meaning:'A scroll that unlocks a recipe; Wren sells several.',link:'characters/wren'},{term:'Salvage',meaning:'Breaking a tool back into half of its ingredients (1.3).'},],},NAVBOX,],};const characters={slug:'characters',title:'Characters and factions',cats:['characters'],image:'wren',summary:'The people of Glimmerdeep - from Wren the Tinkerer to the Hollow King - and the three factions you can earn reputation with.',blocks:[{type:'text',text:'Glimmerdeep has a small cast of named characters and three **factions**. Reputation with a faction rises when you complete its quests and falls when you hurt its members; higher reputation unlocks trades and recipes.'},{type:'pagelist',title:'Characters with their own articles',source:'children',style:'cards',summary:true},{type:'text',text:'## Factions\n### Lantern Guild\nExplorers and mapmakers who keep a hall on the frozen lake of [[world#Frostfen|Frostfen]]. They sell maps and lantern upgrades and give the questline that ends with the Frost Crown. [[characters/wren|Wren]] was once a member.\n\n'+'### Rootkin\nThe quiet moss-folk of the [[biomes/mossy-hollows|Mossy Hollows]], led by Old Mother Brindle. They trade seeds, rope and Puffcap Spores, and they will not trade with anyone who kills [[creatures/glowmoth|Glowmoths]].\n\n'+'### Ashborn\nA fire-worshipping order in the [[world#Ashen Spires|Ashen Spires]]. Hostile at first; reputation can be earned only after the [[creatures/ember-wyrm|Ember Wyrm]] is defeated. {{spoiler|They believe the Hollow King stole their god’s light.}}',},{type:'table',caption:'Factions compared',head:'row',striped:true,rows:[['Faction','Home','Leader','Starting attitude','Best reward'],['Lantern Guild','Frostfen','Guildmaster Osk','Friendly','Frost Crown (key)'],['Rootkin','Mossy Hollows','Old Mother Brindle','Neutral','Everbloom seeds'],['Ashborn','Ashen Spires','The Cinder Voice','Hostile','Ember Cloth armour']],},NAVBOX,],};const wren={slug:'characters/wren',parent:'characters',title:'Wren the Tinkerer',cats:['characters'],image:'wren',summary:'The inventor of the Mossy Hollows: repairs tools, sells blueprints and gives the questline that unlocks the Tinker’s Bench.',blocks:[{type:'infobox',title:'Wren',subtitle:'the Tinkerer',image:'wren',caption:'Character portrait',color:'#2f6f6a',rows:[{label:'Role',value:'Merchant, quest giver'},{label:'Location',value:'Wren’s Workshop, [[biomes/mossy-hollows|Mossy Hollows]]'},{label:'Faction',value:'[[characters#Lantern Guild|Lantern Guild]] (former)'},{label:'Services',value:'Repairs, blueprints, shard trading'},{label:'Added in',value:'0.1; questline in [[patch-history|1.3]]'},{label:'NPC ID',value:'`npc:wren`',layer:'ids'},],},{type:'text',text:'**Wren** is an inventor who lives in a cottage workshop a short walk from the Starting Glade. She is the first character most players meet, and the one they visit most: she repairs tools, sells blueprints and owns the only [[crafting#Tinker’s Bench|Tinker’s Bench]] you can use before building your own.\n\n'+'## Quests',},{type:'table',head:'row',striped:true,rows:[['Quest','Requirements','Reward'],['A Light in the Moss','Bring 5 Glow Dust','[[items/storm-lantern|Storm Lantern]] blueprint'],['Spare Parts','Bring 4 Copper Ingots and 2 [[items/glimmer-shard|Glimmer Shards]]','Tinker’s Bench recipe'],['The Tinker’s Toolbox','Defeat the [[creatures/ember-wyrm|Ember Wyrm]] (1.3)','Wren’s Toolbox (key)'],['Letters to Nobody','{{spoiler|Read all six letters in the workshop}}','{{spoiler|A locket with a portrait of the Hollow King}}'],],},{type:'quote',style:'block',text:'Everything broken can be mended. Nearly everything. Bring me a shard and we’ll argue about the rest.',author:'Wren',source:'greeting, version 1.3'},{type:'text',text:'## Relationships\nWren left the [[characters#Lantern Guild|Lantern Guild]] years before the game begins and refuses to say why. {{spoiler|Her letters show that she knew the Hollow King before he took the throne.}} The full story is part of the [[lore]].',},NAVBOX,],};const hollowKing={slug:'characters/hollow-king',parent:'characters',title:'The Hollow King',cats:['characters','bosses'],image:'king',summary:'The final boss of Glimmerdeep, waiting on a throne in the deepest layer of the Glimmer Caverns. Contains spoilers.',blocks:[SPOILER_WARNING,{type:'infobox',title:'The Hollow King',image:'king',caption:'Character portrait',color:'#3b2f5a',rows:[{label:'Role',value:'Final boss, antagonist'},{label:'Location',value:'{{spoiler|The Hollow Throne, deepest layer of the [[biomes/glimmer-caverns|Glimmer Caverns]]}}'},{label:'Health',value:'2,000'},{label:'Former faction',value:'[[characters#Lantern Guild|Lantern Guild]]'},{label:'Added in',value:'1.0 “The Deep Update”'},{label:'NPC ID',value:'`boss:hollow_king`',layer:'ids'},],},{type:'text',text:'The **Hollow King** is the antagonist of Glimmerdeep and its final boss. Most of the game’s myths blame him for the darkness: the [[lore|story]] says he swallowed the light of the First Lantern and sank with it into the earth, where it shattered into [[items/glimmer-shard|Glimmer Shards]].\n\n'+'## Reaching him\nThe throne room opens only with three keys: the Ember Heart from the [[creatures/ember-wyrm|Ember Wyrm]], the Frost Crown from the [[characters#Lantern Guild|Lantern Guild]] and Wren’s Toolbox from [[characters/wren|Wren]].\n\n'+'## Background\nHe was once {{spoiler|the Lantern Guild’s keeper of the First Lantern}}. His crown is {{spoiler|the guild’s old lantern frame, bent into a circle}}.',},{type:'callout',kind:'spoiler',title:'The endings (major spoilers)',text:'After the fight, the player chooses what to do with the light the King has been holding:\n\n- **Relight** - the First Lantern is restored and the world gets its sun back; the Glimmer Caverns go dark for ever.\n- **Keep the Dark** - the light stays scattered in the shards, and the King’s last line names the world “Glimmerdeep”.\n\nThe community has long suspected a third ending; see the [[lore]] page.',},NAVBOX,],};const guideBeginner=[{type:'callout',kind:'tip',title:'Beginner version',text:'New to Glimmerdeep? This version covers your first three in-game nights step by step. Switch to **Advanced** above for routes, numbers and speedrun tricks.'},{type:'text',text:'Your first nights in Glimmerdeep are the hardest: it gets dark quickly, and darkness hurts. This guide gets you from the Starting Glade in the [[biomes/mossy-hollows|Mossy Hollows]] to your first trip underground.\n\n'+'## Night one: light and shelter\n1. Pull moss from rocks to get **moss fibre**, and punch a tree for **wood**.\n2. Make a **Workbench** (10 wood) - see [[crafting]].\n3. Make torches and a small hut before the sun sets.\n4. Stay inside or near a fire at night. The darkness meter only fills away from light.\n\n'+'## Night two: copper\n1. Make a Wooden Pickaxe and mine copper ore on the riverbanks.\n2. Build a Forge and smelt your first Copper Ingots.\n3. Visit [[characters/wren|Wren]] and take her first quest, *A Light in the Moss*.\n\n'+'## Night three: your first lantern\nCatch Glow Dust from [[creatures/glowmoth|Glowmoths]] (they come to your torches), finish Wren’s quest and build a [[items/storm-lantern|Storm Lantern]]. Now you are ready for the [[biomes/glimmer-caverns|Glimmer Caverns]].',},{type:'flashcards',title:'Quick quiz',items:[{front:'What fills the darkness meter?',back:'Being away from any light source. A lantern, torch, fire or shard cluster keeps it empty.'},{front:'Who gives the first quest?',back:'[[characters/wren|Wren]], in her workshop near the Starting Glade.'},{front:'What fuels a Storm Lantern?',back:'Glow Dust from Glowmoths (or Ember Oil later).'},],},NAVBOX,];const guideAdvanced=[{type:'callout',kind:'info',title:'Advanced version',text:'Assumes you know the basics. Numbers are for version 1.3, normal difficulty. Switch to **Beginner** above for the step-by-step version.'},{type:'text',text:'## The efficient opening\nThe fastest safe route reaches the Shardfields before the fourth night. The key idea is to skip the Copper Pickaxe entirely: trade with [[characters/wren|Wren]] for your first two [[items/glimmer-shard|Glimmer Shards]] and go straight to the [[items/glimmer-pickaxe|Glimmer Pickaxe]].',},{type:'table',caption:'Route timings (in-game hours)',head:'row',sortable:true,striped:true,rows:[['Step','Target time','Notes'],['Workbench + torches','0:40','Pull moss while walking to the trees'],['Copper (8 ore)','3:10','East riverbank has the densest ore'],['Wren: both quests','6:30','Bring Glow Dust from torch-lit moths'],['Glimmer Pickaxe','9:00','Shards bought from Wren'],['Shardfields','11:30','Through the north-east sinkhole']],},{type:'text',text:'## Darkness maths\nThe darkness meter fills at 1 point per second in full dark and drains at 3 points per second in light; at 100 you lose 2 health per second. A tamed [[creatures/glowmoth|Glowmoth]] halves the fill rate, which is why advanced players tame one before the Caverns rather than carrying a second [[items/storm-lantern|lantern]].\n\n'+'## Fuel efficiency',},{type:'table',head:'row',sortable:true,compact:true,rows:[['Fuel','Minutes per unit','Units per stack','Minutes per stack'],['Glow Dust','4','99','396'],['Ember Oil','10','32','320'],['Shard Wick','25','16','400']],},{type:'callout',kind:'warning',title:'Patch note',text:'Routes that dig straight down with the Glimmer Pickaxe stopped working in 1.2, when its speed was cut; see [[patch-history]].'},{type:'text',text:'## Before the bosses\nFor the [[creatures/ember-wyrm|Ember Wyrm]], six Frost Resin bombs are enough if you bomb only when it rears; the phase 2 lava rain cannot hit you inside a two-block-deep hole.'},NAVBOX,];const firstNights={slug:'guides/first-nights',title:'Guide: Surviving your first nights',cats:['guides'],image:'hollows',summary:'A strategy guide to the first nights of Glimmerdeep, in a Beginner and an Advanced version.',versions:[{id:'beginner',label:'Beginner',blocks:guideBeginner},{id:'advanced',label:'Advanced',blocks:guideAdvanced}],};const loreSong={type:'verse',title:'Song of the Lantern-bearers (in-game book)',numbers:'none',text:'Carry the light where the light has gone,\nkeep it low and keep it on.\nThe sun was glass and the glass was thin,\nand the dark came out and the dark came in.\n\nOne went down with the light in hand,\none stayed up to guard the land.\nWhen both come home and the gate is wide,\nthe sun will rise on the other side.',source:'Found on a lectern in the Lantern Guild Hall',};const lore={slug:'lore',title:'Lore',cats:['lore'],image:'mural',summary:'The story behind Glimmerdeep as the game tells it: the First Lantern, the Darkening and the Hollow King.',blocks:[{type:'media',media:'mural',align:'full',caption:'The Lantern Mural in the Glimmer Caverns: the King, the First Lantern and the Wyrm.'},{type:'text',text:'Glimmerdeep tells its story through books, murals and a few conversations rather than cutscenes. This page collects what the game says openly. Spoilers are hidden until clicked.\n\n'+'## The First Lantern\nLong ago the Hollowed Lands were lit by the **First Lantern**, a sun made of crystal that hung above the centre of the world. The [[characters#Lantern Guild|Lantern Guild]] was founded to tend it.\n\n'+'## The Darkening\nOne day the light went out. The myths agree that a keeper of the Lantern took the light into the earth, where it broke into the [[items/glimmer-shard|Glimmer Shards]]. The keeper became [[characters/hollow-king|the Hollow King]].\n\n'+'## The wyrms\nThe Ashborn of the [[world#Ashen Spires|Ashen Spires]] say the [[wyrm|wyrms]] are the children of the Lantern’s fire. Only one is left: the [[creatures/ember-wyrm|Ember Wyrm]].',},loreSong,{type:'callout',kind:'info',title:'Is there more?',text:'Players have long suspected that the game hides a third ending. This wiki keeps the datamined material on a hidden version of this page - see the [[help#The hidden lore|help page]] for how to open it.'},NAVBOX,],variants:[{password:'lore451',label:'The hidden lore',note:'Hidden lore (demo password lore451)',versions:[{id:'story',label:'The story',blocks:[{type:'callout',kind:'important',title:'The hidden lore',text:'You are reading the hidden version of this page: unused dialogue and files found in the game data, pieced together by the community. Nothing here is confirmed by Pebblefox Studio.'},{type:'media',media:'mural',align:'full',caption:'Read the mural again: the King is not taking the light. He is carrying it.'},{type:'text',text:'## The keeper did not steal the light\nUnused lines of [[characters/hollow-king|the Hollow King]] say that the First Lantern was cracking, and that the Ashborn meant to seize its fire. The keeper carried the light underground to hide it, knowing it would break - and that he would be blamed.\n\n'+'## The Wyrm was guarding, not hoarding\nThe [[creatures/ember-wyrm|Ember Wyrm]] is the Lantern’s last guardian. The Ember Heart it curls around is the core of the First Lantern, kept apart from the shards so that no one could rebuild the sun by force.\n\n'+'## Wren\n[[characters/wren|Wren]] is the Hollow King’s granddaughter. The six letters in her workshop are addressed to him; the seventh, found only in the files, is her answer to his last line.\n\n'+'## The third ending: “The Long Dawn”\nA cut ending lets the player return the Ember Heart to the Wyrm instead of using it. The Wyrm uncoils, carries the light to the surface slowly, over a hundred in-game days, and both the caverns and the sky keep some of it. The song of the [[characters#Lantern Guild|Lantern-bearers]] - “one went down, one stayed up” - is its only trace in the finished game.',},loreSong,NAVBOX,],},{id:'sources',label:'Sources & unused files',blocks:[{type:'text',text:'Where the hidden lore comes from. File names are as found in version 1.3.2.'},{type:'table',head:'row',striped:true,rows:[['File','Contents','Used in game?'],['`dlg_king_unused.txt`','41 lines of the Hollow King','No'],['`letter_07.txt`','Wren’s seventh letter','No'],['`ending_dawn.scene`','The “Long Dawn” ending, without audio','No'],['`mural_lantern.png`','The Lantern Mural','Yes']],},{type:'callout',kind:'note',title:'Datamined',layer:'datamined',text:'The 1.4 beta renames `ending_dawn.scene` to `ending_03.scene` - a sign, some think, that it may yet be finished.'},NAVBOX,],},],}],};const patchHistory={slug:'patch-history',title:'Patch history',cats:['meta'],image:'worldmap',summary:'Every major version of Glimmerdeep from the 2022 pre-alpha to the 1.4 beta, with what each one added.',blocks:[{type:'text',text:'Glimmerdeep has been updated regularly since its first public playtest. Major versions have names; small fixes (1.2.1 and so on) are listed on the pages of the things they changed, such as the [[creatures/ember-wyrm|Ember Wyrm]] and the [[items/glimmer-pickaxe|Glimmer Pickaxe]].'},{type:'timeline',title:'Versions',style:'line',items:[{date:'2 May 2022',title:'0.1 Pre-alpha',text:'First public playtest: the [[biomes/mossy-hollows|Mossy Hollows]] (then called “The Green”), the Workbench and [[characters/wren|Wren]].'},{date:'17 February 2023',title:'0.5 Early Access',text:'The [[biomes/glimmer-caverns|Glimmer Caverns]], the darkness meter, [[creatures/glowmoth|Glowmoths]], the [[items/storm-lantern|Storm Lantern]] and the [[items/glimmer-pickaxe|Glimmer Pickaxe]].{{ref|{{cite|author=Pebblefox Studio|title=Glimmerdeep enters Early Access|work=Pebblefox developer log|year=2023}}}}'},{date:'14 March 2024',title:'1.0 “The Deep Update”',text:'Full release: [[characters/hollow-king|the Hollow King]], the two endings, co-op for four players.'},{date:'20 November 2024',title:'1.1 “Frostfen”',text:'[[world#Frostfen|Frostfen]], [[creatures#Frost Wisp|Frost Wisps]], the Lantern Guild questline.'},{date:'8 August 2025',title:'1.2 “Embers”',text:'[[world#Ashen Spires|The Ashen Spires]], the [[creatures/ember-wyrm|Ember Wyrm]], the Ashborn; Glimmer Pickaxe speed reduced.{{ref|{{cite|author=Pebblefox Studio|title=Glimmerdeep 1.2 “Embers” patch notes|work=Pebblefox developer log|year=2025}}}}'},{date:'30 June 2026',title:'1.3 “Tinker’s Toolbox”',text:'Wren’s questline, salvage, Shard Wicks and a [[crafting|crafting]] overhaul.'},{date:'September 2026',title:'1.4 “Sunshard” (beta)',text:'Public beta of the [[world#Sunshard Dunes|Sunshard Dunes]].'},],},{type:'table',caption:'Versions compared',head:'row',sortable:true,striped:true,rows:[['Version','Name','Released','New biome','New boss'],['0.1','Pre-alpha','2022-05-02','Mossy Hollows','-'],['0.5','Early Access','2023-02-17','Glimmer Caverns','-'],['1.0','The Deep Update','2024-03-14','-','The Hollow King'],['1.1','Frostfen','2024-11-20','Frostfen','-'],['1.2','Embers','2025-08-08','Ashen Spires','Ember Wyrm'],['1.3','Tinker’s Toolbox','2026-06-30','-','-']],},{type:'callout',kind:'note',title:'Datamined (unconfirmed)',layer:'datamined',text:'Strings in the 1.4 beta mention a version “2.0” with the subtitle “The Long Dawn”. See the [[lore]] page.'},{type:'references'},NAVBOX,],};const help={slug:'help',title:'Help: About this wiki',cats:['meta'],summary:'How the Glimmerdeep Wiki works: spoilers, versions, layers, redirects, the hidden lore and the editing rules.',blocks:[{type:'text',text:'The **Glimmerdeep Wiki** is written by players for players. It is not affiliated with Pebblefox Studio. (Glimmerdeep, Pebblefox Studio and everything on this wiki are fictional - this is an example knowledge base you can turn into your own.)\n\n'+'## Spoiler policy\nArticles about late-game content start with a spoiler warning. Inside articles, plot details are hidden behind **inline spoilers** - click a blurred phrase to reveal it, like this: {{spoiler|the Hollow King was once a lantern keeper}} - and longer passages sit in collapsed **spoiler boxes**, as on [[characters/hollow-king|the Hollow King]].\n\n'+'## Reading tools\n- **Versions:** some pages come in more than one version. The [[guides/first-nights|first-nights guide]] has a *Beginner* and an *Advanced* version; pick one under the title.\n- **Layers:** the *Technical IDs* layer shows item, creature and biome IDs in infoboxes; the *Datamined* layer shows unconfirmed information from game files. Both are off by default - switch them on under a page title.\n- **Map:** the [[world|world map]] is clickable; hover a region for a preview.\n- **Hover previews:** point at any link to see the start of the page.\n\n'+'## Redirects and disambiguation\nA **redirect** sends one name to another article: [[wyrm]] leads to the Ember Wyrm. A **disambiguation page** lists the articles a name can mean: see [[lantern]].\n\n'+'## The hidden lore\nThe [[lore]] page has a hidden version, “The hidden lore”, with datamined dialogue and the cut third ending. It is a **451 variant**: it is encrypted in the published wiki and opens only with a password. To read it, open the lore page with `#?451=lore451` appended to the address, or enter the password `lore451` on the [[special:unlock|unlock page]].\n\n'+'## Editing guidelines\n- Write for players: what something does, where to find it, how to use it.\n- Give numbers for the current version and say which version they come from.\n- Put story details in spoilers; put unconfirmed information in the *Datamined* layer.\n- Add a [[patch-history|patch history]] entry when an update changes a page.',},NAVBOX,],};const lanternDisambig={slug:'lantern',title:'Lantern (disambiguation)',cats:['disambiguation'],summary:'Lantern may refer to the Storm Lantern item, the Lantern Guild faction or the First Lantern of the myths.',blocks:[{type:'disambig',intro:'**Lantern** may refer to:',items:[{link:'items/storm-lantern',label:'Storm Lantern',desc:'the portable light source fuelled by Glow Dust'},{link:'characters#Lantern Guild',label:'Lantern Guild',desc:'the faction of explorers based in Frostfen'},{link:'lore#The First Lantern',label:'The First Lantern',desc:'the crystal sun of the creation myth'},{link:'crafting',label:'Shard Lamp',desc:'a placeable light made from a Glimmer Shard (see the recipe table)'},],},{type:'callout',kind:'note',title:'Disambiguation page',text:'If a link led you here, you may want to change it to point straight at the intended article. See [[help#Redirects and disambiguation|help]].'},],};const wyrmRedirect={slug:'wyrm',title:'Wyrm',kind:'redirect',target:'creatures/ember-wyrm'};const __default={id:'fandom',icon:'star',name:{en:'Game fan wiki',ru:'Фан-вики игры',uk:'Фан-вікі гри',de:'Fan-Wiki zum Spiel',fr:'Wiki de fans de jeu',es:'Wiki de fans de un juego',ka:'თამაშის ფან-ვიკი'},desc:{en:'A fan wiki of an invented crafting game: infoboxes, recipes, stats, a world map, spoilers and patch history.',ru:'Фан-вики выдуманной игры про крафт: инфобоксы, рецепты, характеристики, карта мира, спойлеры и история патчей.',uk:'Фан-вікі вигаданої гри про крафт: інфобокси, рецепти, характеристики, мапа світу, спойлери та історія патчів.',de:'Ein Fan-Wiki zu einem erfundenen Crafting-Spiel: Infoboxen, Rezepte, Werte, Weltkarte, Spoiler und Patch-Historie.',fr:'Le wiki de fans d’un jeu d’artisanat inventé : infobox, recettes, statistiques, carte du monde, spoilers et historique des patchs.',es:'La wiki de fans de un juego de crafteo inventado: fichas, recetas, estadísticas, mapa del mundo, spoilers e historial de parches.',ka:'გამოგონილი ქრაფტინგ-თამაშის ფან-ვიკი: ინფობოქსები, რეცეპტები, მახასიათებლები, მსოფლიოს რუკა, სპოილერები და პატჩების ისტორია.',},spec(){return{title:'Glimmerdeep Wiki',tagline:'The fan encyclopedia of the crafting game Glimmerdeep',lang:'en',uiLang:'en',theme:'fandom-dark',accent:'#4fd1c5',logo:'shard',home:'main-page',nav:[{label:'World',link:'world'},{label:'Creatures',link:'creatures'},{label:'Items',link:'items'},{label:'Crafting',link:'crafting'},{label:'Characters',link:'characters'},{label:'Guide',link:'guides/first-nights'},{label:'Patches',link:'patch-history'},{label:'Help',link:'help'},],footer:'**Glimmerdeep Wiki** is a fan wiki of a fictional game, made as a template. Glimmerdeep, Pebblefox Studio and every character, place and patch note here are invented.\n\n[[help|About this wiki]] · [[help#Spoiler policy|Spoiler policy]] · [[patch-history|Patch history]]',license:'Community content of this template may be reused and adapted freely.',layers:[{id:'ids',label:'Technical IDs',on:false},{id:'datamined',label:'Datamined',on:false},],cats:[{slug:'biomes',name:'Biomes',desc:'The regions of the Hollowed Lands. Overview and map: [[world]].'},{slug:'creatures',name:'Creatures',desc:'Every creature, passive or hostile. Stats table: [[creatures]].'},{slug:'bosses',name:'Bosses',desc:'Boss fights and how to win them.'},{slug:'items',name:'Items',desc:'Everything you can carry. Overview: [[items]].'},{slug:'tools',name:'Tools',desc:'Pickaxes, lanterns and other equipment.'},{slug:'resources',name:'Resources',desc:'Materials you mine, gather or loot.'},{slug:'characters',name:'Characters',desc:'Named characters and factions.'},{slug:'guides',name:'Guides',desc:'How-to articles and strategy guides.'},{slug:'lore',name:'Lore',desc:'The story of Glimmerdeep. Contains spoilers.'},{slug:'meta',name:'Wiki',desc:'Pages about the game’s versions and about this wiki.'},{slug:'disambiguation',name:'Disambiguation pages',desc:'Pages that list the articles a name can refer to.'},],media,pages:[mainPage,world,mossyHollows,glimmerCaverns,creatures,glowmoth,emberWyrm,items,glimmerShard,glimmerPickaxe,stormLantern,crafting,characters,wren,hollowKing,firstNights,lore,patchHistory,help,lanternDisambig,wyrmRedirect],};},};export{__default};